    TwistExpander_Antares_Arx::KEY_A_D_D(PARAMS_SEED);

    KeyDiffuse_B_A_D(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Antares_Arx::KEY_A_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(ANTARES_KEY_A_D_IceLaneA, ANTARES_KEY_A_D_IceLaneB, ANTARES_KEY_A_D_IceLaneC, ANTARES_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

    // Key flow — A / E

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
