    TwistSquash::SquashKeyA(ANTARES_KEY_A_E_IceLaneA, ANTARES_KEY_A_E_IceLaneB, ANTARES_KEY_A_E_IceLaneC, ANTARES_KEY_A_E_IceLaneD, &(pWorkSpace->mKeyBoxA[4U][0]));

