    KeyDiffuse_A_B_D(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Antares_Arx::KEY_B_D_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Antares_Arx::KEY_B_D_D(PARAMS_SEED);

    KeyDiffuse_B_B_D(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
