    TwistSquash::SquashKeyA(ANTARES_KEY_B_E_IceLaneA, ANTARES_KEY_B_E_IceLaneB, ANTARES_KEY_B_E_IceLaneC, ANTARES_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

    // Key flow — B / F

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
