    std::uint8_t *aGozLaneC = pWorkSpace->mAuguryLaneC;
    std::uint8_t *aMuLaneD = pWorkSpace->mCelestialLaneD;
    std::uint8_t *aLelLaneD = pWorkSpace->mAlchemyLaneD;
