    KEY_FOLD_BLOCK(aCrystalLaneA, 10U, 327U, aCrystalLaneD, 35U, 386U, aMuLaneB, 1U);

    // Mu B[2]: aCrystalLaneD[25] + aEarthLaneB[49].
    KEY_FOLD_BLOCK(aCrystalLaneD, 25U, 108U, aEarthLaneB, 49U, 352U, aMuLaneB, 2U);

